package com.industrial.defect.entity.keyboard;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="keyboard_inspections") public class KeyboardInspection {
 @Id private UUID id; @Column(name="original_filename") private String originalFilename; @Column(name="device_info") private String deviceInfo;
 @Column(name="layout_type") private String layoutType; @Column(name="source_image_url") private String sourceImageUrl; @Column(name="display_image_url") private String displayImageUrl;
 private String status; private boolean success; @Column(name="has_defect") private boolean hasDefect; @Column(name="analysis_json",columnDefinition="TEXT") private String analysisJson; @Column(name="total_ms") private Double totalMs;
 @Column(name="created_at") private OffsetDateTime createdAt; @Column(name="updated_at") private OffsetDateTime updatedAt;
 @PrePersist void created(){if(id==null)id=UUID.randomUUID(); var now=OffsetDateTime.now(); if(createdAt==null)createdAt=now;updatedAt=now;} @PreUpdate void updated(){updatedAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public void setId(UUID v){id=v;} public String getOriginalFilename(){return originalFilename;} public void setOriginalFilename(String v){originalFilename=v;} public void setDeviceInfo(String v){deviceInfo=v;} public String getDeviceInfo(){return deviceInfo;} public void setLayoutType(String v){layoutType=v;} public String getLayoutType(){return layoutType;} public void setSourceImageUrl(String v){sourceImageUrl=v;} public String getSourceImageUrl(){return sourceImageUrl;} public void setDisplayImageUrl(String v){displayImageUrl=v;} public String getDisplayImageUrl(){return displayImageUrl;} public void setStatus(String v){status=v;} public String getStatus(){return status;} public void setSuccess(boolean v){success=v;} public boolean isSuccess(){return success;} public void setHasDefect(boolean v){hasDefect=v;} public boolean isHasDefect(){return hasDefect;} public void setAnalysisJson(String v){analysisJson=v;} public String getAnalysisJson(){return analysisJson;} public void setTotalMs(Double v){totalMs=v;} public Double getTotalMs(){return totalMs;} public OffsetDateTime getCreatedAt(){return createdAt;}
}
